mapper.delete:
delete from ems_metric_history_5min
where tenant_id = #{tenantId}
  and bucket_time < #{beforeTime}

delete from ems_sync_log
where tenant_id = #{tenantId}
  and coalesce(last_occurred_at, finished_at, create_time) < #{beforeTime}

delete from ems_report_sync_task
where tenant_id = #{tenantId}
  and create_time < #{beforeTime}

delete from ems_openems_backfill_task
where tenant_id = #{tenantId}
  and create_time < #{beforeTime}

delete from ems_openems_resource_report
where tenant_id = #{tenantId}
  and stat_time < #{beforeTime}
